    /// What a rule carries from line to line.
    /// A rule whose patterns include another language's grammar carries that
    /// language's state, when its feature is on.
    /// A rule whose end repeats a begin capture group carries that group.
    #[expect(clippy::too_many_lines, reason = "a generated table")]
    #[inline]
    pub(crate) fn carried_state(self) -> rules::CarriedState {
        match self {
            Rule::Root
            | Rule::CommentsAt0
            | Rule::PhpDocAt3
            | Rule::PhpDocTypesArrayMultiple
            | Rule::Nested0
            | Rule::Nested1
            | Rule::ClassNameAt0
            | Rule::Namespace
            | Rule::ClassNameAt2
            | Rule::CommentsAt1
            | Rule::CommentsAt2
            | Rule::CommentsAt2At0
            | Rule::CommentsAt3
            | Rule::CommentsAt3At0
            | Rule::Nested2
            | Rule::LanguageAt1
            | Rule::LanguageAt2
            | Rule::Nested3
            | Rule::LanguageAt4
            | Rule::LanguageAt4At2
            | Rule::LanguageAt6
            | Rule::LanguageAt6At1
            | Rule::Nested4
            | Rule::ScopeResolutionAt1
            | Rule::LanguageAt7
            | Rule::LanguageAt7At1
            | Rule::LanguageAt7At1At0
            | Rule::LanguageAt7At2
            | Rule::LanguageAt7At2At1
            | Rule::LanguageAt7At3
            | Rule::SwitchStatementAt1
            | Rule::SwitchStatementAt1At0
            | Rule::LanguageAt10
            | Rule::LanguageAt11
            | Rule::Nested5
            | Rule::LanguageAt13
            | Rule::LanguageAt13At0
            | Rule::FunctionParametersAt2
            | Rule::RegexDoubleQuoted
            | Rule::InterpolationAt4
            | Rule::Nested6
            | Rule::LanguageAt14
            | Rule::Nested7
            | Rule::SqlStringDoubleQuotedAt5
            | Rule::SqlStringDoubleQuotedAt6
            | Rule::StringDoubleQuoted
            | Rule::RegexSingleQuoted
            | Rule::RegexSingleQuotedAt2
            | Rule::StringSingleQuoted
            | Rule::StringBacktick
            | Rule::VariablesAt4
            | Rule::LanguageAt20
            | Rule::ObjectAt0
            | Rule::ObjectAt1
            | Rule::HeredocAt0
            | Rule::HeredocInteriorAt7At3
            | Rule::HeredocInteriorAt7At5
            | Rule::HeredocAt1
            | Rule::Nested8
            | Rule::FunctionCallAt0
            | Rule::Nested9
            | Rule::Nested10
            | Rule::SupportAt1
            | Rule::FunctionCallAt1
            | Rule::LanguageAt42
            | Rule::Instantiation
            | Rule::LanguageAt47
            | Rule::LanguageAt48
            | Rule::LanguageAt49
            | Rule::ParameterDefaultTypesAt7
            | Rule::ParameterDefaultTypesAt9
            | Rule::Nested11
            | Rule::FunctionParametersAt4
            | Rule::FunctionParametersAt4At0
            | Rule::FunctionParametersAt6
            | Rule::RegexDoubleQuotedAt3
            | Rule::LanguageAt13At1
            | Rule::SwitchStatementAt1At1
            | Rule::Nested12
            | Rule::UseInnerAt1 => rules::CarriedState::None,
            Rule::SqlStringDoubleQuoted
            | Rule::SqlStringSingleQuoted
            | Rule::HeredocInteriorAt3
            | Rule::NowdocInteriorAt3 => embedded!(Sql, "lang-sql")
                .map_or(rules::CarriedState::None, rules::CarriedState::Embed),
            Rule::HeredocInteriorAt0 | Rule::NowdocInteriorAt0 => embedded!(Html, "lang-html")
                .map_or(rules::CarriedState::None, rules::CarriedState::Embed),
            Rule::HeredocInteriorAt1 | Rule::NowdocInteriorAt1 => embedded!(Blade, "lang-blade")
                .map_or(rules::CarriedState::None, rules::CarriedState::Embed),
            Rule::HeredocInteriorAt2 | Rule::NowdocInteriorAt2 => embedded!(Xml, "lang-xml")
                .map_or(rules::CarriedState::None, rules::CarriedState::Embed),
            Rule::HeredocInteriorAt4Javascript
            | Rule::HeredocInteriorAt4Js
            | Rule::NowdocInteriorAt4Javascript
            | Rule::NowdocInteriorAt4Js => embedded!(JavaScript, "lang-javascript")
                .map_or(rules::CarriedState::None, rules::CarriedState::Embed),
            Rule::HeredocInteriorAt5 | Rule::NowdocInteriorAt5 => embedded!(Json, "lang-json")
                .map_or(rules::CarriedState::None, rules::CarriedState::Embed),
            Rule::HeredocInteriorAt6 | Rule::NowdocInteriorAt6 => embedded!(Css, "lang-css")
                .map_or(rules::CarriedState::None, rules::CarriedState::Embed),
            Rule::HeredocInteriorAt7 | Rule::HeredocInteriorAt8 => rules::CarriedState::Backref(3),
            Rule::NowdocInteriorAt7 | Rule::NowdocInteriorAt8 => rules::CarriedState::Backref(2),
        }
    }

